    "lbl_full_name": "ಪೂರ್ಣ ಹೆಸರು *",
    "lbl_mobile": "ಮೊಬೈಲ್ ಸಂಖ್ಯೆ *",
    "gender_label": "ಲಿಂಗ *",
    "gender_male": "ಆಂಜೊವು",
    "gender_female": "ಪೊಂಜೊವು",
